import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { sendCodeHandler } from "../handlers/sendCodeHandler";
import type { ApiError } from "../runtime/client";
import type { SendCodeRequest } from "../types/SendCodeRequest";

type Data = Awaited<ReturnType<typeof sendCodeHandler>>;
type Vars = SendCodeRequest;

export function useSendCode(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => sendCodeHandler(vars),
    ...options,
  });
}
